    supported_algorithms = ['sha512_256', 'sha224', 'sha384', 'sha512_224', 'sha512', 'sm3', 'sha1', 'sha3_384', 'shake_128', 'sha256', 'blake2b', 'md5-sha1', 'shake_256', 'ripemd160', 'md5', 'sha3_256', 'blake2s', 'sha3_512', 'sha3_224']

