def create_api_redirect_url(base_url_api, api_endpoint, opts=None):
    if not base_url_api or not api_endpoint:
        raise ValueError("Base URL and API endpoint cannot be empty.")

    parsed_url = urllib.parse.urlparse(base_url_api)
    if parsed_url.netloc not in APPROVED_API_DOMAINS:
        raise ValueError(f"Base URL {parsed_url.netloc} is not allowed.")

    if api_endpoint not in ALLOWED_ENDPOINTS:
        raise ValueError(f"API endpoint {api_endpoint} is not allowed.")

    if opts and not isinstance(opts, dict):
        raise ValueError("Query parameters must be a dictionary.")

    for key, value in opts.items():
        if not isinstance(value, str):
            raise ValueError("Query parameters must be strings.")

    redirect_url = urllib.parse.urlunparse((parsed_url.scheme, parsed_url.netloc, api_endpoint, None, None, None))
    if opts:
        redirect_url += "?" + urllib.parse.urlencode(opts)

    return redirect_url

